<script setup lang="ts">const { toast, close } = useToast()</script>
<template><Transition enter-active-class="transition duration-200" enter-from-class="translate-y-2 opacity-0" leave-active-class="transition duration-150" leave-to-class="translate-y-2 opacity-0"><div v-if="toast" class="fixed bottom-5 right-5 z-[100] flex max-w-[calc(100vw-2.5rem)] items-center gap-3 rounded-lg border px-4 py-3 text-sm font-medium shadow-lg" :class="toast.type === 'error' ? 'border-danger-border bg-danger-bg text-danger' : toast.type === 'info' ? 'border-brand-mid bg-brand-light text-brand' : 'border-success-border bg-success-bg text-success'" role="status" aria-live="polite"><span>{{ toast.message }}</span><button type="button" class="opacity-60 hover:opacity-100" aria-label="Dismiss notification" @click="close">×</button></div></Transition></template>
